let graphSelected='',graphConnectFrom='',graphZoom=1;
const graphLine=key=>state.lines.find(l=>l.processKey===key);
function graphGeometryHTML(l,p){if(p.error)return `<p class="small">${esc(p.error)}</p>`;return `<div class="graph-metric"><span class="small">${p.finished?'Геометрия готовых деталей':l.processBinding?'Геометрия исходного материала':'Характеристики материала'} / партия</span><br>Площадь: <b>${dec(p.values?.area)} м²</b></div><div class="small">Масса материала: ${dec(p.values?.mass)} кг<br>Длина материала: ${dec(p.values?.length)} м</div>`;}
function graphEnsureKeys(){let changed=false;if(state.version!==3&&state.lines.length){state.version=3;state.schemaVersion=3;changed=true;}for(const l of state.lines)if(!l.processKey){l.processKey=uid();if(l.kind==='material'&&!l.processBinding&&!l.processMetrics){const m=ProcessGraphCore.catalogMetrics(l,CATALOG.find(c=>c.id===l.catalogId));if(Object.keys(ProcessGraphCore.METRICS).some(k=>m[k]!==null)){l.processMetrics=m;l.confirmed=false;}}changed=true;}if(changed)persist();}
function graphLayout(){const columns=new Map(),positions=new Map(),byKey=new Map(state.lines.map(l=>[l.processKey,l]));function depth(l,seen=new Set()){if(!l.processBinding)return l.kind==='material'?0:1;if(seen.has(l.processKey))return 1;seen.add(l.processKey);const parent=byKey.get(l.processBinding.from);return Math.min(12,parent?depth(parent,seen)+1:1);}for(const l of state.lines){const d=depth(l),index=columns.get(d)||0;columns.set(d,index+1);positions.set(l.processKey,l.processPosition||{x:40+d*330,y:55+index*290});}return positions;}
function renderProcessGraph(){if(typeof window!=='undefined')window.GraphReact?.unmount();if(state.lines.some(l=>!l.processKey)){ $('app').innerHTML=title('Материал → процесс','Технологическая схема','Связи управляют объёмами работ.','Настройка')+`<div class="card"><h2>Подготовить состав к связям</h2><p>Позиций: ${state.lines.length}. Включение схемы добавит идентификаторы и доступные характеристики материалов; потребуется повторная проверка и согласование.</p><button class="primary" onclick="graphEnsureKeys();render()">Включить связи для текущего состава</button><button onclick="go(2)">К списку работ</button></div>`;return;}if(graphConnectFrom&&!graphLine(graphConnectFrom))graphConnectFrom='';if(graphSelected&&!graphLine(graphSelected))graphSelected='';const positions=graphLayout(),resolved=ProcessGraphCore.resolve(state),effective=new Map(resolved.state.lines.map(l=>[l.processKey,l])),width=Math.max(1050,...[...positions.values()].map(p=>p.x+320)),height=Math.max(620,...[...positions.values()].map(p=>p.y+280));
 const paths=state.lines.filter(l=>l.processBinding).map(l=>{const a=positions.get(l.processBinding.from),b=positions.get(l.processKey);if(!a||!b)return '';const x=a.x+268,y=a.y+105,tx=b.x,ty=b.y+105,mid=(x+tx)/2;return `<path d="M${x},${y} C${mid},${y} ${mid},${ty} ${tx},${ty}"/>`;}).join('');
 $('app').innerHTML=title('Материал → процесс','Технологическая схема','Соедините выход материала со входом процесса. Узлы можно перемещать за заголовок.','Пробная версия')+`<div class="toolbar"><button onclick="picker('material')">Добавить материал</button><button onclick="picker('work')">Добавить работу</button><button onclick="graphAddOperation()">Расчётная операция</button><button onclick="addManual('work')">Своя работа</button><button onclick="graphArrange()">Расположить автоматически</button><label>Масштаб <select aria-label="Масштаб схемы" onchange="graphSetZoom(Number(this.value))">${[.6,.8,1,1.2].map(z=>`<option value="${z}" ${graphZoom===z?'selected':''}>${Math.round(z*100)}%</option>`).join('')}</select></label><button onclick="go(2)">К списку работ</button></div><p class="note info" id="graph-status" role="status">${graphConnectFrom?'Выбран выход: '+esc(graphLine(graphConnectFrom)?.name)+'. Нажмите «Вход» нужного процесса.':'Выберите узел для настройки характеристик и связи. Связи пересчитывают объёмы в калькуляции; закупочный запас в обработку не переносится.'}</p><div class="graph-layout"><div class="graph-viewport" id="graph-viewport" aria-label="Схема материалов и процессов"><div class="graph-scaled" style="width:${width*graphZoom}px;height:${height*graphZoom}px"><div class="graph-canvas" id="graph-canvas" style="width:${width}px;height:${height}px;transform:scale(${graphZoom})"><svg class="graph-wires" width="${width}" height="${height}" aria-hidden="true"><defs><marker id="graph-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z"/></marker></defs>${paths}</svg>${state.lines.map(l=>{const p=positions.get(l.processKey),e=effective.get(l.processKey),physical=ProcessGraphCore.physical(l.processKey,state.lines,state.qty),b=l.processBinding;return `<article class="graph-node ${l.kind==='material'&&!b?'graph-material':'graph-process'} ${graphSelected===l.processKey?'graph-selected':''}" id="node-${l.processKey}" data-key="${l.processKey}" style="left:${p.x}px;top:${p.y}px"><button class="graph-node-head" data-drag-key="${l.processKey}" onclick="graphSelect('${l.processKey}')" aria-label="Настроить узел ${esc(l.name)}"><small>${l.kind==='material'&&!b?'МАТЕРИАЛ':l.kind==='material'?'РАСХОДНИК':'ПРОЦЕСС'}</small><strong>${esc(l.name)||'Без названия'}</strong></button><div class="graph-node-body"><span class="small">${esc(l.group)} · ${l.scope==='batch'&&!l.operation?'партия':'на изделие'}</span><div class="graph-ports"><button onclick="graphInput('${l.processKey}')" aria-label="Вход узла ${esc(l.name)}">● Вход</button><button onclick="graphOutput('${l.processKey}')" aria-label="Выход узла ${esc(l.name)}">Выход ●</button></div><div class="small">${l.operation?'Объём обработки: '+dec(e.operation?.[l.operation.mode==='machine'?'minutes':'measure'])+' '+esc(ProcessGraphCore.targetUnit(l)):'Объём: '+dec(e.qty)+' '+esc(MaterialCore.unitLabel(l.unit))}</div>${graphGeometryHTML(l,physical)}<div class="small">${esc(graphBindingDescription(b,l))}</div></div></article>`;}).join('')}${!state.lines.length?'<p class="graph-empty">Добавьте материал и работу, затем соедините их.</p>':''}</div></div></div><section class="card graph-inspector" id="graph-inspector">${graphInspectorHTML(graphLine(graphSelected))}</section></div>${resolved.errors.length?`<div class="note"><h3>Уточните связи</h3>${resolved.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:''}<p class="small">Площадь узла — физический объём материала без запаса, на всю партию. Для процессов на изделие она делится на тираж. Длина материала не равна автоматически длине реза. Перед применением проверьте поверхности обработки, единицы и нормы.</p>`;
 const host=$('graph-viewport'),react=typeof window!=='undefined'?window.GraphReact:null;
 const model={zoom:graphZoom,nodes:state.lines.map(l=>({id:l.processKey,type:'calculator',position:positions.get(l.processKey),selected:graphSelected===l.processKey,data:{line:l,effective:effective.get(l.processKey),physical:ProcessGraphCore.physical(l.processKey,state.lines,state.qty),targetUnit:ProcessGraphCore.targetUnit(l),binding:graphBindingDescription(l.processBinding,l)}})),edges:state.lines.filter(l=>l.processBinding&&graphLine(l.processBinding.from)).map(l=>({id:l.processBinding.from+'-'+l.processKey,source:l.processBinding.from,target:l.processKey,sourceHandle:'output',targetHandle:'input',markerEnd:{type:'arrowclosed'}}))};
 if(react?.mount(host,model)){host.classList.add('react-graph');return;}
 graphInstallDrag();graphDrawWires();}
function graphInspectorHTML(l){if(!l)return '<h2>Настройки узла</h2><p>Нажмите заголовок узла. Здесь можно задать площадь, массу и длину материала или настроить автоматический объём процесса.</p>';
 const p=graphLayout().get(l.processKey),b=l.processBinding;return `<h2>${esc(l.name)||'Узел'}</h2><p class="small">${esc(l.source)}</p><div class="mini-actions"><button onclick="editLine('${l.id}')">Ставка и количество</button>${l.kind==='material'&&!b?`<button onclick="graphMetricsDialog('${l.processKey}')">Характеристики материала</button>`:''}<button onclick="graphBindingDialog('${l.processKey}')">${b?'Настроить связь':'Привязать вход'}</button>${l.kind==='work'?`<button onclick="graphOutputDialog('${l.processKey}')">Готовые детали после процесса</button>`:''}</div>${graphRecommendationsHTML(l)}${b?`<p>Источник: ${esc(graphLine(b.from)?.name||'Удалённый узел')}</p><p>${esc(graphBindingDescription(b,l))}</p><p class="small">${esc(b.note)}</p><button onclick="graphDetach('${l.processKey}')">Снять связь и оставить текущий объём</button>`:''}<details><summary>Положение узла без перетаскивания</summary><form onsubmit="graphPosition(event,'${l.processKey}')"><div class="grid2"><div class="field"><label for="node-x">По горизонтали</label><input id="node-x" type="number" min="0" max="20000" value="${p.x}"></div><div class="field"><label for="node-y">По вертикали</label><input id="node-y" type="number" min="0" max="20000" value="${p.y}"></div></div><button>Переместить</button></form></details>`;}
function graphSelect(key){graphSelected=key;if($('graph-inspector'))$('graph-inspector').innerHTML=graphInspectorHTML(graphLine(key));document.querySelectorAll('.graph-node').forEach(n=>n.classList.toggle('graph-selected',n.dataset.key===key));}
function graphOutput(key){graphConnectFrom=key;$('graph-status').textContent='Выбран выход: '+graphLine(key).name+'. Нажмите «Вход» процесса или выберите узел и «Привязать вход».';}
function graphInput(key){graphBindingDialog(key,graphConnectFrom);}
function graphAddOperation(){modal('Добавить расчётную операцию',`<div class="mini-actions">${Object.entries(OperationsCore.TYPES).map(([k,t])=>`<button onclick="operationDialog(null,'${k}')">${esc(t.name)}</button>`).join('')}</div><p>После сохранения операция появится на схеме. Для связи используйте вход узла.</p>`);}
function graphMetricsDialog(key){const l=graphLine(key);if(!l||l.kind!=='material')return;const m=l.processMetrics&&ProcessGraphCore.unit(l.processMetrics.unit)===ProcessGraphCore.unit(l.unit)?l.processMetrics:ProcessGraphCore.catalogMetrics({...l,processMetrics:undefined},CATALOG.find(c=>c.id===l.catalogId));modal('Характеристики материала',`<form onsubmit="graphSaveMetrics(event,'${key}')"><h3>${esc(l.name)}</h3><p>Все значения — на одну <b>${esc(MaterialCore.unitLabel(l.unit))}</b> материала. Количество материала и тираж умножаются отдельно. Пустое поле означает неизвестное значение.</p><div class="grid2">${Object.entries(ProcessGraphCore.METRICS).map(([k,t])=>`<div class="field"><label for="metric-${k}">${esc(t.name)}, ${esc(MaterialCore.unitLabel(t.unit))} / ${esc(MaterialCore.unitLabel(l.unit))}</label><input id="metric-${k}" type="number" min="0" step="any" value="${m[k]??''}"></div>`).join('')}</div><div class="field"><label for="metric-source">Основание характеристик</label><input id="metric-source" value="${esc(m.source)}" required></div><label class="checkrow"><input id="metric-confirm" type="checkbox" required>Проверены единица материала и поверхности, которые действительно обрабатываются</label><p class="small">Из справочника могут быть предложены площадь всех поверхностей и площадь одной стороны. Это разные характеристики; геометрия раскроя автоматически не определяется.</p><p id="graph-error" role="alert"></p><button class="primary">Сохранить характеристики</button></form>`);}
function graphSaveMetrics(e,key){e.preventDefault();const l=graphLine(key),m={unit:l.unit,source:$('metric-source').value.trim()};if(!$('metric-confirm').checked||!m.source)return;for(const k of Object.keys(ProcessGraphCore.METRICS))m[k]=$('metric-'+k).value===''?null:Number($('metric-'+k).value);try{ProcessGraphCore.validate([{...l,processMetrics:m}]);l.processMetrics=m;l.confirmed=false;persist();$('modal').close();render();}catch(e){$('graph-error').textContent=e.message;}}
function graphDetach(key){const l=graphLine(key);if(!l?.processBinding)return;const effective=ProcessGraphCore.resolve(state).state.lines.find(x=>x.processKey===key);if(l.operation)l.operation=effective.operation;else l.qty=effective.qty;delete l.processBinding;l.confirmed=false;persist();render();}
function graphPosition(e,key){e.preventDefault();const p={x:Number($('node-x').value),y:Number($('node-y').value)};if(Object.values(p).some(v=>!Number.isFinite(v)||v<0||v>20000))return;graphLine(key).processPosition=p;persist();render();}
function graphArrange(){state.lines.forEach(l=>delete l.processPosition);persist();render();}
function graphSetZoom(z){if(![.6,.8,1,1.2].includes(z))return;graphZoom=z;render();}
function graphDrawWires(){const canvas=$('graph-canvas');if(!canvas?.getBoundingClientRect)return;const svg=canvas.querySelector('.graph-wires'),rect=canvas.getBoundingClientRect();for(const path of [...svg.querySelectorAll(':scope > path')])path.remove();for(const l of state.lines){if(!l.processBinding)continue;const a=$('node-'+l.processBinding.from),b=$('node-'+l.processKey);if(!a||!b)continue;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),out=a.querySelector('.graph-ports button:last-child').getBoundingClientRect(),input=b.querySelector('.graph-ports button:first-child').getBoundingClientRect(),x=(ar.right-rect.left)/graphZoom,y=(out.top+out.height/2-rect.top)/graphZoom,tx=(br.left-rect.left)/graphZoom,ty=(input.top+input.height/2-rect.top)/graphZoom,mid=(x+tx)/2,path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${x},${y} C${mid},${y} ${mid},${ty} ${tx},${ty}`);svg.append(path);}}
function graphInstallDrag(){const canvas=$('graph-canvas');if(!canvas?.addEventListener)return;canvas.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag-key]');if(!handle||e.button!==0)return;const node=handle.closest('.graph-node'),key=handle.dataset.dragKey,startX=e.clientX,startY=e.clientY,origin={x:parseFloat(node.style.left),y:parseFloat(node.style.top)};let moved=false;handle.setPointerCapture(e.pointerId);const move=ev=>{const dx=ev.clientX-startX,dy=ev.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;if(moved){node.style.left=Math.max(0,Math.min(20000,origin.x+dx/graphZoom))+'px';node.style.top=Math.max(0,Math.min(20000,origin.y+dy/graphZoom))+'px';graphDrawWires();}};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);if(moved){graphLine(key).processPosition={x:parseFloat(node.style.left),y:parseFloat(node.style.top)};persist();render();}};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);});}
(function(){const previousEdit=editLine;editLine=function(id){previousEdit(id);const l=state.lines.find(l=>l.id===id);if(!l?.processBinding||l.processBinding.mode==='context')return;const e=ProcessGraphCore.resolve(state).state.lines.find(x=>x.processKey===l.processKey),input=l.operation?$('op-'+(l.operation.mode==='machine'?'minutes':'measure')):$('l-qty');if(input){input.value=l.operation?e.operation[l.operation.mode==='machine'?'minutes':'measure']??'':e.qty??'';input.disabled=true;}if($('modalBody'))$('modalBody').insertAdjacentHTML('afterbegin','<p class="note info">Объём берётся из связи на технологической схеме. Для ручного ввода выберите режим «Материал подключён · объём вручную» в настройках связи.</p>');};})();
